import React, { useState, useEffect } from "react";
import { View, FlatList, Text } from "react-native";
import AsyncStorage from "@react-native-async-storage/async-storage";
import { Nota } from "./src/componentes/Nota";
import NotaEditor from "./src/componentes/NotaEditor";


export default function App() {
  const [notas, setNotas] = useState([]);
  const [notaEditando, setNotaEditando] = useState(null);

  const mostraNotas = async () => {
    try {
      const todasChaves = await AsyncStorage.getAllKeys();
      const todasNotas = await AsyncStorage.multiGet(todasChaves);

      const notasFormatadas = todasNotas
        .filter(([chave, valor]) => valor !== null && valor !== undefined && valor.trim() !== "")
        .map(([chave, valor]) => {
          try {
            // Tenta parsear como JSON (com categoria)
            const notaParseada = JSON.parse(valor);
            return [chave, notaParseada.texto, notaParseada.categoria || "Pessoal"];
          } catch (e) {
            // Se não for JSON, usa como texto simples com categoria padrão
            return [chave, valor, "Pessoal"];
          }
        });

      setNotas(notasFormatadas);
    } catch (error) {
      console.error("Erro ao carregar notas:", error);
    }
  };

  const editarNota = (nota) => {
    // nota é um array [id, texto, categoria]
    setNotaEditando({
      id: nota[0],
      texto: nota[1],
      categoria: nota[2] || "Pessoal"
    });
  };

  const cancelarEdicao = () => {
    setNotaEditando(null);
  };

  useEffect(() => {
    mostraNotas();
  }, []);

  return (
    <View style={{ flex: 1, paddingTop: 50 }}>
      <Text style={{ fontSize: 24, fontWeight: "bold", textAlign: "center", marginBottom: 20 }}>
        Minhas Notas
      </Text>

      <FlatList
        data={notas}
        keyExtractor={(item) => item[0]}
        renderItem={({ item }) => (
          <Nota 
            item={item} 
            onPress={() => editarNota(item)}
          />
        )}
        ListEmptyComponent={
          <Text style={{ textAlign: "center", marginTop: 20, padding: 16, color: "#666" }}>
            Nenhuma nota encontrada. Clique no + para criar uma nova nota.
          </Text>
        }
      />

      <NotaEditor 
        mostraNotas={mostraNotas}
        notaEditando={notaEditando}
        onCancelarEdicao={cancelarEdicao}
      />
    </View>
  );
}
